#!/usr/bin/env bash
set -Eeuo pipefail
cd "$(dirname "$0")"
if [[ -s Server/HytaleServer.jar && -s Assets.zip && -s start.sh ]]; then
  echo "[Hytale] Existing game installation preserved."
  exit 0
fi
if [[ -e Server || -e Assets.zip || -e start.sh ]]; then
  echo "[Hytale] Partial game files found. Inspect the installation before retrying." >&2
  exit 1
fi
command -v qemu-x86_64-static >/dev/null || { echo "[Hytale] QEMU user-mode is required for the official amd64 downloader. On Ubuntu: sudo apt install qemu-user-static" >&2; exit 127; }
command -v python3 >/dev/null || { echo "[Hytale] Python 3 is required." >&2; exit 127; }
[[ -f downloader/hytale-downloader-linux-amd64 ]] || { echo "[Hytale] Official downloader not extracted." >&2; exit 1; }
echo "[Hytale] Use the device-code URL shown below to authorize the official download."
(cd downloader && qemu-x86_64-static ./hytale-downloader-linux-amd64 -download-path game.zip)
[[ -s downloader/game.zip ]] || { echo "[Hytale] Official downloader did not produce game.zip." >&2; exit 1; }
python3 - <<'PY'
from pathlib import Path, PurePosixPath
from zipfile import ZipFile
import shutil
root=Path.cwd()
staging=root/".hytale-stage"
if staging.exists(): raise SystemExit("Old staging directory found; inspect it before retrying")
staging.mkdir()
try:
    with ZipFile(root/"downloader/game.zip") as z:
        for f in z.infolist():
            name=PurePosixPath(f.filename.replace("\\","/"))
            if name.is_absolute() or ".." in name.parts:
                raise ValueError("Unsafe path in download archive")
        z.extractall(staging)
    for p in ("Server/HytaleServer.jar","Assets.zip","start.sh"):
        if not (staging/p).is_file(): raise ValueError("Unexpected game archive structure: "+p)
    for p in ("Server","Assets.zip","start.sh","start.bat"):
        if (staging/p).exists():
            if (root/p).exists(): raise ValueError("Destination already exists: "+p)
            shutil.move(str(staging/p),str(root/p))
    (root/"start.sh").chmod(0o755)
finally:
    shutil.rmtree(staging,ignore_errors=True)
(root/"downloader/game.zip").unlink()
print("[Hytale] Server files installed.")
PY
